"""Exploratory shape/count scope check; no population claim from three seeds."""
import csv,json,statistics,math
from pathlib import Path
root=Path(__file__).resolve().parent/'extension';raw=json.loads((root/'results.json').read_text())
assert len(raw)==36 and len({(r['dataset'],r['method']) for r in raw})==36
rows=[]
for run in raw:
 truth=json.loads((root/'data'/run['dataset']/'truth.json').read_text());result=run.get('result',{})
 row={k:v for k,v in run.items() if k not in ['result','command']};row.update(effect=truth['effect'],shape=truth['shape'],seed=truth['seed'],status=result.get('status','failed'))
 if row['status']=='complete':
  assert row['exit_code']==0 and not row['timed_out'];selected=result['selected'];pred={tuple(sorted([c] if isinstance(c,str) else c)) for c in selected['shift_clades']};actual=set(map(tuple,truth['shift_clades']));tp=len(pred&actual)
  assert len(actual)==5 and len(pred)<=10 and set(selected['predicted'])==set(truth['tip_mean'])
  row.update(f1=2*tp/(len(pred)+5),mean_rmse=math.sqrt(statistics.mean((selected['predicted'][n]-m)**2 for n,m in truth['tip_mean'].items())),selected_shifts=len(pred))
 rows.append(row)
keys=list(dict.fromkeys(k for r in rows for k in r))
with (root/'metrics.csv').open('w') as f:
 writer=csv.DictWriter(f,fieldnames=keys);writer.writeheader();writer.writerows(rows)
summary=[]
for shape in ['balanced','random']:
 for effect in [2,6]:
  for method in ['baseline','candidate','kfl1ou']:
   runs=[r for r in rows if r['shape']==shape and r['effect']==effect and r['method']==method];valid=[r for r in runs if r['status']=='complete'];r={'shape':shape,'effect':effect,'method':method,'runs':len(runs),'complete':len(valid)}
   for key in ['f1','mean_rmse','selected_shifts']:r[key]=statistics.mean(x[key] for x in valid) if valid else None
   for key in ['wall_seconds','peak_rss_mib']:r[key]=statistics.median(x[key] for x in runs)
   summary.append(r)
(root/'summary.json').write_text(json.dumps(summary,indent=2)+'\n')
lines=['# Tree shape and unknown-count scope check','','Three new paired seeds per shape and effect; 100 tips, five true shifts, cap ten. This is an exploratory scope check, not a precise population comparison.','','| Shape | Effect | Method | Complete | F1 | Mean RMSE | Mean shifts | Median seconds | Median RSS MiB |','| --- | --- | --- | --- | --- | --- | --- | --- | --- |']
for r in summary:
 lines.append(f"| {r['shape']} | {r['effect']} | {r['method']} | {r['complete']}/{r['runs']} | {r['f1']:.3f} | {r['mean_rmse']:.3f} | {r['selected_shifts']:.2f} | {r['wall_seconds']:.2f} | {r['peak_rss_mib']:.1f} |")
lines+=['','The random ultrametric tree is generated by backward random pair merging with positive exponential time increments, then normalized to height one. This is a declared simulation design, not a claim about a biological tree-generating process. Shifted clades are disjoint and contain 3–10 tips. Identical optimum effect scale does not imply identical observed mean separation across shapes, because shift ages differ.','','[Protocol](../PROTOCOL.md) · [Primary 30-seed comparison](../RESULTS.md) · [Individual runs](metrics.csv)']
(root/'RESULTS.md').write_text('\n'.join(lines)+'\n')
